import {
	createContext,
	createEffect,
	createMemo,
	createSignal,
	JSX,
	on,
	onCleanup,
	onMount,
	useContext,
	type ParentComponent,
} from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { InputEngineEvent, NavigateInputEvent } from "#core/ui/input/input-support.js";
import { SolidAdapterContext } from "#core/ui-next/components/fxs-solid-component.js";
import { TooltipModel } from "#core/ui-next/components/tooltip-model.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import {
	DefaultNavigationRules,
	FocusContext,
	FocusContextProvider,
	FocusNavigationRulesMap,
	isContextFocusable,
	isFocusableAFocusContext,
} from "#core/ui-next/services/focus.js";
import { HotkeyContext, HotkeyContextProvider, useHotkeyContext } from "#core/ui-next/services/hotkey.js";
import { ActiveInputDevice, EngineInputProxyContext, EngineInputProxyProvider } from "#core/ui-next/services/input.js";
import { createPropsRefSignal, PropsRef } from "#core/ui-next/utilities/solid-utilities.js";

export class PanelStackContextProvider {
	constructor(private onChildClosed: () => void) {}

	public triggerChildClosed() {
		this.onChildClosed();
	}
}

export const PanelStackContext = createContext<PanelStackContextProvider>();

const NAV_REPEAT_INITIAL_THRESHOLD = 400;
const NAV_REPEAT_THRESHOLD = 150;

export interface PanelProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/**
	 *  The name of the panel. This is used for various tracking contexts like focus.
	 *  Because of this, it should never be changed after initialization.
	 */
	name: string;
	/** Sets the DOM class attribute  */
	class?: string;
	/** Gets a reference of the component. For more info see {@link https://docs.solidjs.com/concepts/refs Refs}  */
	ref?: PropsRef<HTMLDivElement>;
	/** The navigation order of the component. Default: Vertical */
	navRules?: FocusNavigationRulesMap;
	/** Gets the id of the panel. Should match the id used to push this panel into the context manager */
	id: string;
	/** The cancel input handler - if not set the default behavior is to close the panel */
	onCancelInput?: () => void;
	/** Auto focus this element? - default: true */
	autoFocus?: boolean;
	/** Automatically appy an input context when this view is active */
	inputContext?: InputContext;
	/* On context changed do something */
	onContextChanged?: (activatedElement: Element, deactivatedElement: Element) => void;
}

const PanelComponent: ParentComponent<PanelProps> = (props) => {
	const adapterContext = useContext(SolidAdapterContext);
	const [root, setRoot] = createPropsRefSignal<HTMLElement>(() => props.ref);
	const hotkeyProvider = new HotkeyContextProvider(useHotkeyContext());
	const engineInputProxyProvider = new EngineInputProxyProvider();

	const resolvedNavRules = createMemo(() => props.navRules ?? DefaultNavigationRules.vertical);
	const useAutoFocus = createMemo(() => props.autoFocus ?? true);
	const [isActiveContext, setIsActiveContext] = createSignal<boolean>(false);

	let navRepeatThreshold = 0;
	let navRepeatTimestamp = 0;

	const onClosePanel = () => {
		ContextManager.pop(props.id);
	};

	const parentStackContext = useContext(PanelStackContext);

	function handleContextChanged(args: { detail: { activatedElement: Element; deactivatedElement: Element } }) {
		const isActive = args.detail.activatedElement == adapterContext?.rootElement;
		setIsActiveContext(isActive);

		if (props.onContextChanged) {
			props.onContextChanged(args.detail.activatedElement, args.detail.deactivatedElement);
		}
	}

	const stackProvider = new PanelStackContextProvider(applyContext);

	onMount(() => {
		document.addEventListener("close-panel", onClosePanel);
		engine.on("OnContextManagerChanged", handleContextChanged);

		hotkeyProvider.mount();

		applyContext(false);
	});

	onCleanup(() => {
		document.removeEventListener("close-panel", onClosePanel);
		engine.off("OnContextManagerChanged", handleContextChanged);
		hotkeyProvider.cleanup();
		parentStackContext?.triggerChildClosed();
	});

	const navigationHandler = (context: FocusContextProvider, action: InputNavigationAction) => {
		// If a child context is focused, let it try to handle the navigation
		const curFocus = context.currentFocus();
		if (isFocusableAFocusContext(curFocus)) {
			if (curFocus.navigate(action)) {
				return true;
			}
		}

		// Otherwise, try to handle the navigation using the provided rules
		if (resolvedNavRules().get(action)?.(context)) {
			return true;
		}

		// If focus wasn't handled elsewhere, refocus the current element
		context.focusCurrentOrDefault();
		return true;
	};

	// eslint-disable-next-line solid/reactivity
	const focusProvider = new FocusContextProvider(root, navigationHandler, props.name);

	// If nothing was focused, and we now have a child and when the device type changes, try to focus it.
	// Dont mess with this unless you know what you are doing - it might break solid to legacy focus shifting.
	createEffect(
		on(
			() => [ActiveInputDevice(), focusProvider.hasChildren(), isActiveContext()],
			([device, hasChildren], prev) => {
				const isController = device == InputDeviceType.Controller;

				// Only refocus if controller is active and we have focusable children
				if (isController && hasChildren) {
					const sameDevice = device == prev?.[0]; // PrevDevice
					const curFocus = FocusManager.get().currentFocus();
					const isCurFocusSolidFocus = curFocus?.hasAttribute("data-focus-context-name");
					const isBodyFocus = curFocus == document.body;

					// Only refocus if children changed and a solid element or no element has focus (leave legacy focus intact)
					if (sameDevice || !curFocus || isCurFocusSolidFocus || isBodyFocus) {
						hotkeyProvider.refresh();
						focusProvider.focusCurrentOrDefault();
					}
				}
			},
		),
	);

	function applyContext(applyFocus = true) {
		if (applyFocus) {
			focusProvider.focusCurrentOrDefault();
		}

		if (props.inputContext) {
			Input.setActiveContext(props.inputContext);
		}

		if (adapterContext?.rootElement) {
			adapterContext.rootElement.dispatchEvent = (e) => root()?.dispatchEvent(e) ?? false;
		}
	}

	/**
	 * Handles navigation events entering this panel.
	 * @param navigationEvent The navigation event to handle
	 */
	function onNavigate(navigationEvent: NavigateInputEvent) {
		if (hotkeyProvider.onInput(navigationEvent)) {
			// Handled by hotkey
			return;
		}

		if (navigationEvent.detail.status == InputActionStatuses.START) {
			navRepeatThreshold = NAV_REPEAT_INITIAL_THRESHOLD;
			navRepeatTimestamp = Date.now();
			return;
		} else if (navigationEvent.detail.status == InputActionStatuses.UPDATE) {
			const now = Date.now();
			if (navRepeatThreshold > 0 && now >= navRepeatTimestamp + navRepeatThreshold) {
				navRepeatThreshold = NAV_REPEAT_THRESHOLD;
				navRepeatTimestamp = now;
			} else {
				return;
			}
		} else if (navigationEvent.detail.status == InputActionStatuses.FINISH) {
			navRepeatThreshold = 0;
			navRepeatTimestamp = 0;
		} else {
			return;
		}

		if (focusProvider.navigate(navigationEvent.detail.navigation)) {
			navigationEvent.preventDefault();
			navigationEvent.stopPropagation();
		}
	}

	/**
	 * Forwards input events to the active element & proxies inside this panel
	 * Panels act as coordinators for all controller events within them
	 */
	function onEngineInput(event: InputEngineEvent) {
		if (hotkeyProvider.onInput(event)) {
			// Handled by hotkey
			return;
		}

		if (
			(event.isCancelInput() || event.detail.name == "keyboard-escape") &&
			event.detail.status == InputActionStatuses.FINISH
		) {
			const tooltipModel = TooltipModel.get();
			if (tooltipModel.locked()) {
				tooltipModel.unlockAll();
			} else if (props.onCancelInput) {
				props.onCancelInput();
			} else {
				ContextManager.pop(ContextManager.getCurrentTarget());
			}

			event.preventDefault();
			event.stopPropagation();
			return;
		}

		const activeElement = document.activeElement;
		const isControllerEvent = !(event.detail.isMouse || event.detail.isTouch);
		let proxyEvent = event;

		// If we are using a controller and focus is not valid, try to fix it.
		if (isControllerEvent) {
			// If we are using a controller, forward the event to the active element.
			// For performance reasons, this is a direct dispatch and will not bubble.
			// (Not using else here because the previous setupFocus() call could change the activeElement).
			if (activeElement?.getAttribute("data-focus-context-name") == props.name) {
				// Copy the event with bubbling disabled
				proxyEvent = InputEngineEvent.CreateNewEvent(event, false);
				activeElement.dispatchEvent(proxyEvent);
			}
		}

		// If it wasnt handled, forward it to the input proxy context
		if (!event.defaultPrevented) {
			engineInputProxyProvider.triggerEngineInput(event);
		}
	}

	return (
		<div
			{...props}
			ref={setRoot}
			class={`pointer-events-auto ${props.class}`}
			data-name={props.name}
			tabIndex={-1}
			on:navigate-input={onNavigate}
			on:engine-input={onEngineInput}
			onFocus={() => applyContext()}
			use:isContextFocusable={[focusProvider, true, useAutoFocus()]}
		>
			<PanelStackContext.Provider value={stackProvider}>
				<FocusContext.Provider value={focusProvider}>
					<EngineInputProxyContext.Provider value={engineInputProxyProvider}>
						<HotkeyContext.Provider value={hotkeyProvider}>{props.children}</HotkeyContext.Provider>
					</EngineInputProxyContext.Provider>
				</FocusContext.Provider>
			</PanelStackContext.Provider>
		</div>
	);
};

/**
 * The parent component for all top-level screens and panels.
 * Sets up contexts for focus, input, tooltips and hotkeys.
 * Only a single panel will be active at any given time, allowing for controller and hotkey input.
 * Panels should not be nested.
 * ```tsx
 * <Panel name="tech-tree">
 *  ...
 * </Panel>
 * ```
 * Default implementation: {@link PanelComponent}
 * @param {PanelProps} props See {@link PanelProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {string} props.name The name of the panel. This is used for various tracking contexts like focus.
 */
export const Panel = ComponentRegistry.register("Panel", PanelComponent);
